@push('scripts')<meta name="csrf-token" content="{{ csrf_token() }}"><script>const cards=[...document.querySelectorAll('.post-card')],search=document.getElementById('postSearch');let activeSector='ALL',activeTags=[];function applyFilter(){const q=search.value.toLowerCase();cards.forEach(c=>{const tags=(c.dataset.tags||'').split(/\s+/).filter(Boolean);const show=(activeSector==='ALL'||c.dataset.sector===activeSector)&&activeTags.every(t=>tags.includes(t))&&(c.dataset.search.includes(q));c.classList.toggle('hidden',!show)})}search.addEventListener('input',applyFilter);document.querySelectorAll('.sector').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sector').forEach(x=>x.classList.remove('border-white','bg-pitch-800'));b.classList.add('border-white','bg-pitch-800');activeSector=b.dataset.sector;applyFilter()});function toggleTag(tag){const i=activeTags.indexOf(tag);if(i>=0){activeTags.splice(i,1)}else{activeTags.push(tag)}document.querySelectorAll('.tag-chip').forEach(x=>{if(activeTags.includes(x.dataset.tag)){x.classList.add('border-white','text-white')}else{x.classList.remove('border-white','text-white')}});applyFilter()}
document.querySelectorAll('.tag-chip').forEach(t=>t.onclick=()=>toggleTag(t.dataset.tag));
function addTag(tag){toggleTag(tag);threadModal.classList.add('hidden');threadModal.classList.remove('flex');document.getElementById('postGrid').scrollIntoView({behavior:'smooth'})}
function linkFor(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer nofollow';a.className='break-all text-white underline';a.textContent=url;return a}
function embedFor(url,thumb){let host='';try{host=new URL(url).hostname}catch(e){}
if(/\.(jpe?g|png|gif|webp)(\?[^\s]*)?$/i.test(url)){const img=document.createElement('img');img.src=url;img.loading='lazy';img.alt='embedded image';img.className=thumb?'max-h-40 w-auto border border-silver-700':'my-3 max-h-96 w-auto border border-silver-700';return img}
const yt=url.match(/(?:youtu\.be\/|v=|shorts\/|embed\/)([\w-]{11})/);if(yt&&/(youtube\.com|youtu\.be)/i.test(host)){if(thumb){const img=document.createElement('img');img.src='https://i.ytimg.com/vi/'+yt[1]+'/hqdefault.jpg';img.alt='video thumbnail';img.className='max-h-40 w-auto cursor-pointer border border-silver-700';img.onclick=()=>openPostFromCard(img.closest('.post-card'));return img}const f=document.createElement('iframe');f.src='https://www.youtube.com/embed/'+yt[1];f.className='my-3 w-full aspect-video border border-silver-700';f.allowFullscreen=true;f.loading='lazy';const w=document.createElement('div');w.appendChild(f);return w}
const a=linkFor(url);if(thumb){const w=document.createElement('div');w.className='my-2';w.appendChild(a);return w}return a}
function linkifyNode(node,clickable){[...node.childNodes].forEach(ch=>{if(ch.nodeType===3){const parts=ch.textContent.split(/(^|\s)(#[\w-]+)/g);if(parts.length>1){const frag=document.createDocumentFragment();parts.forEach(p=>{if(/^#[\w-]+$/.test(p)){if(clickable){const b=document.createElement('button');b.className='text-white underline';b.textContent=p;b.onclick=()=>addTag(p.slice(1).toLowerCase());frag.appendChild(b)}else{const s=document.createElement('span');s.textContent=p;frag.appendChild(s)}}else{frag.appendChild(document.createTextNode(p))}});ch.replaceWith(frag)}}else if(ch.nodeType===1&&!ch.classList.contains('post-embeds')&&ch.tagName!=='A'&&ch.tagName!=='BUTTON'){linkifyNode(ch,clickable)}})}
function renderRich(text,el,embeds){el.innerHTML='';const urlRe=/(https?:\/\/[^\s<>"']+)/g;let last=0,m;while((m=urlRe.exec(text))){el.appendChild(document.createTextNode(text.slice(last,m.index)));el.appendChild(embedFor(m[1],false));last=m.index+m[1].length}el.appendChild(document.createTextNode(text.slice(last)));linkifyNode(el,!embeds)}
function openModal(card,full){modalTitle.textContent=card.dataset.title;modalBody.innerHTML='';const media=JSON.parse(card.dataset.media||'[]');(media||[]).forEach(p=>{const img=document.createElement('img');img.src=p.startsWith('posts/')?'/storage/'+p:p;img.alt='attachment';img.className='my-3 max-h-96 w-auto border border-silver-700';modalBody.appendChild(img)});renderRich(card.dataset.body,modalBody,true);threadModal.classList.remove('hidden');threadModal.classList.add('flex')}
function openPostFromCard(card){if(card)openModal(card,true)}
cards.forEach(c=>{const p=c.querySelector('.post-preview');if(p&&c.dataset.body){renderRich(p.textContent,p,false)}
const box=c.querySelector('.post-embeds');const media=JSON.parse(c.dataset.media||'[]');const urls=[...c.dataset.body.matchAll(/(https?:\/\/[^\s<>"']+)/g)].map(x=>x[1]).slice(0,4);media.forEach(p=>{const img=document.createElement('img');img.src=p.startsWith('posts/')?'/storage/'+p:p;img.alt='attachment';img.loading='lazy';img.className='max-h-40 w-auto cursor-pointer border border-silver-700';img.onclick=()=>openModal(c,true);box.appendChild(img)});urls.forEach(u=>{const em=embedFor(u,true);if(em){box.appendChild(em)}})});
const threadModal=document.getElementById('threadModal'),modalTitle=document.getElementById('modalTitle'),modalBody=document.getElementById('modalBody');document.querySelectorAll('.read-post').forEach(b=>b.onclick=()=>openModal(b.closest('.post-card'),true));
document.querySelectorAll('.react-btn').forEach(b=>b.onclick=async e=>{e.preventDefault();const card=b.closest('.post-card');const id=card.dataset.postId;const value=b.dataset.react;try{const r=await fetch('/community/posts/'+id+'/react',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({value:value})});const j=await r.json();if(j.ok){const btns=card.querySelectorAll('.react-btn');btns.forEach(x=>{x.querySelector('.react-count').textContent=x.dataset.react==='up'?j.up:j.down;x.classList.toggle('border-white',x.dataset.react===j.mine);x.classList.toggle('text-white',x.dataset.react===j.mine)})}else{flash(b,'SIGN IN REQUIRED')}}catch(err){flash(b,'SIGN IN REQUIRED')}});function flash(b,txt){const old=b.innerHTML;b.innerHTML=txt;setTimeout(()=>{b.innerHTML=old},1500)}</script>@endpush
